import {
  afterAll,
  beforeAll,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import { randomUUID } from "node:crypto";
import { boundary, usageFixture, usageOwner } from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
const recovery = vi.hoisted(() => ({
  billing: vi.fn(),
  files: vi.fn(),
  decrypt: vi.fn(),
}));
vi.mock("@/lib/billing/deletion", () => ({
  cancelDeletionBilling: recovery.billing,
}));
vi.mock("@/lib/storage", () => ({ deleteOwnedResumes: recovery.files }));
vi.mock("@/lib/crypto", () => ({ decryptToken: recovery.decrypt }));
import { requestAccountDeletion } from "@/lib/account";
import {
  runDeletionJob,
  expireDeletionCredentials,
  DELETION_DRAIN_MS,
  DELETION_RETENTION_MS,
  DELETION_SWEEP_INTERVAL_MS,
} from "@/lib/deletion-jobs";
import { hasDeletionTombstone } from "@/lib/deletion-identity";

describe.runIf(databaseTestsEnabled)("independent deletion jobs", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  const requestedAt = new Date("2026-10-20T12:00:00Z");
  beforeAll(async () => {
    fixture = await usageFixture();
  });
  beforeEach(() => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(requestedAt);
    vi.stubEnv("DELETION_TOMBSTONE_HMAC_KEY", "a".repeat(64));
    recovery.billing.mockReset().mockResolvedValue(true);
    recovery.files.mockReset().mockResolvedValue(undefined);
    recovery.decrypt.mockReset().mockReturnValue("fixture-do-not-log");
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue(new Response(null, { status: 200 })),
    );
  });
  afterAll(async () => {
    vi.useRealTimers();
    vi.unstubAllGlobals();
    vi.unstubAllEnvs();
    if (fixture) await fixture.close();
  });
  async function owner(billing = true) {
    const f = await usageOwner(boundary.db);
    const subject = randomUUID();
    await boundary.db.user.update({
      where: { id: f.user.id },
      data: {
        googleId: subject,
        ...(billing ? { dodoCustomerId: `cus_${randomUUID()}` } : {}),
      },
    });
    return { ...f, subject };
  }
  async function job(userId: string) {
    return boundary.db.accountDeletionJob.findUniqueOrThrow({
      where: { userId },
    });
  }
  it("starts purge exactly at drain and keeps failed storage/billing recovery after removing the identifying User", async () => {
    const f = await owner();
    const audit = await boundary.db.adminAuditLog.create({
      data: {
        actorUserId: f.user.id,
        targetUserId: f.user.id,
        actorIdSnapshot: f.user.id,
        targetIdSnapshot: f.user.id,
        action: "SUSPENSION",
        requestId: randomUUID(),
        requestHash: "a".repeat(64),
        reason: "SUPPORT",
        before: { isSuspended: false },
        after: { isSuspended: false },
      },
    });
    recovery.billing.mockResolvedValue(false);
    recovery.files.mockRejectedValue(new Error("outage"));
    await requestAccountDeletion(f.user.id, f.user.email);
    await runDeletionJob(
      f.user.id,
      new Date(+requestedAt + DELETION_DRAIN_MS - 1),
    );
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).not.toBeNull();
    expect(recovery.files).not.toHaveBeenCalled();
    // Explicit retry due time avoids mistaking a pre-boundary lease schedule for eligibility.
    await boundary.db.accountDeletionJob.update({
      where: { userId: f.user.id },
      data: { nextAttemptAt: requestedAt },
    });
    await runDeletionJob(f.user.id, new Date(+requestedAt + DELETION_DRAIN_MS));
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).toBeNull();
    expect(
      await boundary.db.template.count({ where: { userId: f.user.id } }),
    ).toBe(0);
    expect(await job(f.user.id)).toMatchObject({
      contentDeletedAt: new Date(+requestedAt + DELETION_DRAIN_MS),
      storageDeletedAt: null,
      billingCancelledAt: null,
    });
    expect(
      await boundary.db.adminAuditLog.findUnique({ where: { id: audit.id } }),
    ).toMatchObject({
      actorUserId: null,
      targetUserId: null,
      actorIdSnapshot: f.user.id,
      targetIdSnapshot: f.user.id,
    });
    expect(await hasDeletionTombstone(f.subject)).toBe(true);
    expect(JSON.stringify(await job(f.user.id))).not.toContain(f.user.email);
    recovery.billing.mockResolvedValue(true);
    recovery.files.mockResolvedValue(undefined);
    await runDeletionJob(f.user.id, new Date(+requestedAt + 3600000));
    expect(await job(f.user.id)).toMatchObject({
      billingCancelledAt: expect.any(Date),
      storageDeletedAt: expect.any(Date),
      completedAt: expect.any(Date),
    });
    expect(await hasDeletionTombstone(f.subject)).toBe(false);
  });
  it("attempts billing immediately but leaves physical cleanup to the daily worker, even on repeated requests", async () => {
    const f = await owner();
    await requestAccountDeletion(f.user.id, f.user.email);
    expect(recovery.billing).toHaveBeenCalledExactlyOnceWith(f.user.id);
    expect(await job(f.user.id)).toMatchObject({
      billingCancelledAt: requestedAt,
      contentDeletedAt: null,
    });
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).toMatchObject({ gmailAuthorized: false, encryptedRefreshToken: null });
    vi.setSystemTime(new Date(+requestedAt + 3600000));
    await requestAccountDeletion(f.user.id, f.user.email);
    expect((await job(f.user.id)).contentDeletedAt).toBeNull();
    expect(recovery.files).not.toHaveBeenCalled();
    await runDeletionJob(
      f.user.id,
      new Date(+requestedAt + DELETION_SWEEP_INTERVAL_MS),
    );
    expect((await job(f.user.id)).completedAt).toEqual(
      new Date(+requestedAt + DELETION_SWEEP_INTERVAL_MS),
    );
  });
  it("retains the original request deadline on repeated requests and permanently erases a failed revocation credential", async () => {
    const f = await owner(false);
    vi.mocked(fetch).mockRejectedValue(new Error("Google unavailable"));
    await requestAccountDeletion(f.user.id, f.user.email);
    vi.setSystemTime(new Date(+requestedAt + 60000));
    await requestAccountDeletion(f.user.id, f.user.email);
    expect((await job(f.user.id)).requestedAt).toEqual(requestedAt);
    await runDeletionJob(f.user.id, new Date(+requestedAt + DELETION_DRAIN_MS));
    expect((await job(f.user.id)).encryptedRevocationToken).not.toBeNull();
    await expireDeletionCredentials(
      new Date(
        +requestedAt + DELETION_RETENTION_MS - DELETION_SWEEP_INTERVAL_MS - 1,
      ),
    );
    expect((await job(f.user.id)).encryptedRevocationToken).not.toBeNull();
    await expireDeletionCredentials(
      new Date(
        +requestedAt + DELETION_RETENTION_MS - DELETION_SWEEP_INTERVAL_MS,
      ),
    );
    expect(await job(f.user.id)).toMatchObject({
      encryptedRevocationToken: null,
      googleRevocationIncomplete: true,
    });
    expect(await hasDeletionTombstone(f.subject)).toBe(true);
    await runDeletionJob(
      f.user.id,
      new Date(+requestedAt + DELETION_RETENTION_MS + 1),
    );
    expect((await job(f.user.id)).completedAt).toBeNull();
    expect(await hasDeletionTombstone(f.subject)).toBe(true);
  });
  it("persists cancellation backoff and resumes recovery when the next attempt is due", async () => {
    const f = await owner();
    recovery.billing.mockResolvedValue(false);
    await requestAccountDeletion(f.user.id, f.user.email);
    await runDeletionJob(f.user.id, new Date(+requestedAt + 60000));
    await runDeletionJob(f.user.id, new Date(+requestedAt + 180000));
    expect(await job(f.user.id)).toMatchObject({
      cancellationFailures: 3,
      cancellationAttempts: 3,
      failureCode: "BILLING_CANCELLATION_PENDING",
      nextBillingAttemptAt: new Date(+requestedAt + 420000),
    });
    const attempts = recovery.billing.mock.calls.length;
    await runDeletionJob(f.user.id, new Date(+requestedAt + 240000));
    expect(recovery.billing).toHaveBeenCalledTimes(attempts);
    recovery.billing.mockResolvedValue(true);
    await runDeletionJob(f.user.id, new Date(+requestedAt + 420000));
    expect(await job(f.user.id)).toMatchObject({
      billingCancelledAt: new Date(+requestedAt + 420000),
      failureCode: null,
    });
  });
  it("leases concurrent workers and fences a late subscription against recording cancellation complete", async () => {
    const f = await owner();
    recovery.billing.mockResolvedValue(false);
    await requestAccountDeletion(f.user.id, f.user.email);
    let finish!: () => void, entered!: () => void;
    const started = new Promise<void>((resolve) => {
      entered = resolve;
    });
    const pending = new Promise<void>((resolve) => {
      finish = resolve;
    });
    recovery.billing.mockImplementationOnce(async () => {
      entered();
      await pending;
      return true;
    });
    const at = new Date(+requestedAt + 60000);
    const first = runDeletionJob(f.user.id, at);
    await started;
    expect(await runDeletionJob(f.user.id, at)).toBe(false);
    await boundary.db.accountDeletionJob.update({
      where: { userId: f.user.id },
      data: {
        billingRecoveryVersion: { increment: 1 },
        subscriptionIds: { push: "late-sub" },
      },
    });
    finish();
    await first;
    expect((await job(f.user.id)).billingCancelledAt).toBeNull();
    expect((await job(f.user.id)).subscriptionIds).toContain("late-sub");
  });
});
